ALTER TABLE public.recording_interactions ADD COLUMN parent_comment_id uuid REFERENCES public.recording_interactions(id) ON DELETE CASCADE;
CREATE INDEX recording_comment_parent_idx ON public.recording_interactions(parent_comment_id);
CREATE OR REPLACE FUNCTION public.guard_recording_reply() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.parent_comment_id IS NOT NULL AND (NEW.kind <> 'comment' OR NOT EXISTS (SELECT 1 FROM public.recording_interactions p WHERE p.id=NEW.parent_comment_id AND p.kind='comment' AND p.recording_id=NEW.recording_id AND p.parent_comment_id IS NULL)) THEN RAISE EXCEPTION 'Invalid reply target'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_recording_reply BEFORE INSERT OR UPDATE ON public.recording_interactions FOR EACH ROW EXECUTE FUNCTION public.guard_recording_reply();
CREATE TABLE public.recording_comment_likes (comment_id uuid NOT NULL REFERENCES public.recording_interactions(id) ON DELETE CASCADE, user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(comment_id,user_id));
GRANT SELECT ON public.recording_comment_likes TO anon;
GRANT SELECT,INSERT,DELETE ON public.recording_comment_likes TO authenticated;
GRANT ALL ON public.recording_comment_likes TO service_role;
ALTER TABLE public.recording_comment_likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY comment_likes_read ON public.recording_comment_likes FOR SELECT TO anon,authenticated USING (EXISTS(SELECT 1 FROM public.recording_interactions c WHERE c.id=comment_id AND c.kind='comment' AND public.can_view_recording(c.recording_id)));
CREATE POLICY comment_likes_insert ON public.recording_comment_likes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT public.is_suspended(auth.uid()) AND EXISTS(SELECT 1 FROM public.recording_interactions c WHERE c.id=comment_id AND c.kind='comment' AND public.can_view_recording(c.recording_id)));
CREATE POLICY comment_likes_delete ON public.recording_comment_likes FOR DELETE TO authenticated USING(user_id=auth.uid());
ALTER TABLE public.social_reports ADD COLUMN comment_id uuid REFERENCES public.recording_interactions(id) ON DELETE SET NULL, ADD COLUMN comment_body text;
CREATE OR REPLACE FUNCTION public.guard_comment_report() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE c public.recording_interactions; BEGIN IF NEW.comment_id IS NOT NULL THEN SELECT * INTO c FROM public.recording_interactions WHERE id=NEW.comment_id AND kind='comment'; IF c.id IS NULL OR c.user_id<>NEW.target_user_id OR c.recording_id IS DISTINCT FROM NEW.recording_id OR NOT public.can_view_recording(c.recording_id) THEN RAISE EXCEPTION 'Invalid comment report'; END IF; NEW.comment_body:=c.body; ELSE NEW.comment_body:=NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_comment_report BEFORE INSERT ON public.social_reports FOR EACH ROW EXECUTE FUNCTION public.guard_comment_report();
DROP POLICY report_create ON public.social_reports;
CREATE POLICY report_create ON public.social_reports FOR INSERT TO authenticated WITH CHECK(reporter_id=auth.uid() AND status='open' AND NOT public.is_suspended(auth.uid()) AND ((comment_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.recording_interactions c WHERE c.id=comment_id AND c.kind='comment' AND c.user_id=target_user_id AND c.recording_id=social_reports.recording_id AND public.can_view_recording(c.recording_id))) OR (comment_id IS NULL AND EXISTS(SELECT 1 FROM public.social_identity(ARRAY[target_user_id])) AND (recording_id IS NULL OR EXISTS(SELECT 1 FROM public.voice_recordings v WHERE v.id=social_reports.recording_id AND v.host_id=target_user_id AND public.can_view_recording(v.id))))));